script:
(function () {
  'use strict';
  // Is a paid biweekly payment program worth it on a car loan? Three plans on the same balance:
  //   Monthly: M = L x i / (1 - (1 + i)^-n), i = APR / 12 (M = L / n at 0%), paid monthly.
  //   Paid program: M / 2 debited every 14 days (26 a year). Either the lender credits each half-payment
  //     when it arrives (interest per 14-day period j = APR x 14 / 365), or the program holds the money
  //     and pays the lender M each month plus one extra M every 12th month (13 payments a year).
  //     Fees = setup fee + per-debit fee x number of debits + yearly fee x years enrolled (rounded up).
  //     In the held-and-forwarded case, debits = ceil(total paid to the lender / (M / 2)).
  //   Do it yourself: M + M / 12 paid monthly, no fees (the same 13 payments a year).
  //   Break-even per-debit fee = (interest saved - setup fee - yearly fees) / number of debits.
  // Verified in Node (scratchpad tests/autogroup/bf.test.js): $30,000 at 7% for 60 months = $594.04/mo
  //   and $5,642.16 interest (closed form); the do-it-yourself payoff month equals
  //   ceil(-ln(1 - L i / P) / ln(1 + i)) with P = 13M/12; the credited-biweekly payoff count equals
  //   ceil(-ln(1 - L j / (M/2)) / ln(1 + j)); interest + principal always sums to total paid; at 0% every
  //   plan pays exactly the balance in interest-free dollars; blank, zero and negative inputs show an error
  //   with no NaN or Infinity on the page.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  // Generic amortization: rate per period, payment for period k (1-based). Returns periods and interest.
  function amortize(loan, rate, payFor) {
    var bal = loan, interest = 0, paid = 0, k = 0;
    while (bal > 0.005 && k < 5000) {
      k++;
      var due = bal * rate;
      var pay = Math.min(payFor(k), bal + due);
      interest += due; paid += pay;
      bal = bal + due - pay;
    }
    return { periods: k, interest: interest, paid: paid };
  }

  function plans(o) {
    var i = o.apr / 1200, M = monthlyPayment(o.loan, o.apr / 100, o.months);
    var monthly = amortize(o.loan, i, function () { return M; });
    var prog, debits, months;
    if (o.mode === 'direct') {
      prog = amortize(o.loan, o.apr / 100 * 14 / 365, function () { return M / 2; });
      debits = prog.periods;
      months = debits * 12 / 26;
    } else {
      prog = amortize(o.loan, i, function (k) { return k % 12 === 0 ? 2 * M : M; });
      debits = Math.ceil(prog.paid / (M / 2) - 1e-9);
      months = prog.periods;
    }
    var years = Math.ceil(months / 12 - 1e-9);
    var fees = o.setup + o.perDebit * debits + o.yearly * years;
    var diy = amortize(o.loan, i, function () { return M * 13 / 12; });
    var saved = monthly.interest - prog.interest;
    var maxFee = (saved - o.setup - o.yearly * years) / debits;
    return { M: M, monthly: monthly, prog: prog, progMonths: months, debits: debits, fees: fees, diy: diy,
             saved: saved, net: saved - fees, diySaved: monthly.interest - diy.interest, maxFee: maxFee };
  }

  function duration(months) {
    var m = Math.round(months), y = Math.floor(m / 12), r = m % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (r || !y) parts.push(r + (r === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function clearResults() {
    setText('bfVerdictTitle', '–'); setText('bfVerdict', '');
    ['bfNet', 'bfFees', 'bfDiy', 'bfMaxFee', 'bfPayment', 'bfHalf', 'bfDebits', 'bfSooner'].forEach(function (id) { setText(id, '–'); });
    el('bfTable').innerHTML = '';
  }

  function update() {
    var o = { loan: read('bfLoan'), apr: read('bfApr'), months: read('bfTerm'), setup: read('bfSetup', true),
              perDebit: read('bfPerDebit', true), yearly: read('bfYearly', true), mode: el('bfMode').value };
    var error = el('bfError'), msg = '';
    if (isNaN(o.loan) || o.loan <= 0) msg = 'Enter a loan balance greater than $0.';
    else if (isNaN(o.apr) || o.apr < 0 || o.apr > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if (isNaN(o.months) || o.months < 2 || o.months > 96 || o.months % 1 !== 0) msg = 'Enter 2 to 96 whole months left on the loan.';
    else if ([o.setup, o.perDebit, o.yearly].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Fees cannot be negative.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var r = plans(o);
    var monthsSoonerProg = r.monthly.periods - r.progMonths, monthsSoonerDiy = r.monthly.periods - r.diy.periods;
    setText('bfNet', (r.net < 0 ? '−' : '') + money.format(Math.abs(r.net)));
    setText('bfFees', money.format(r.fees));
    setText('bfDiy', money.format(r.diySaved));
    setText('bfMaxFee', r.maxFee > 0 ? money.format(r.maxFee) : 'None');
    setText('bfPayment', money.format(r.M));
    setText('bfHalf', money.format(r.M / 2));
    setText('bfDebits', String(r.debits));

    if (o.apr === 0) {
      setText('bfVerdictTitle', 'At 0% there is no interest to save');
      setText('bfVerdict', 'Paying faster only moves the payoff date forward, so any program fee is a pure cost of ' + money.format(r.fees) + '.');
    } else if (r.net > 0.005) {
      setText('bfVerdictTitle', 'The program saves ' + money.format(r.net) + ' after fees');
      if (r.diySaved > r.net) {
        setText('bfVerdict', 'Adding ' + money.format(r.M / 12) + ' to each monthly payment yourself saves ' + money.format(r.diySaved) +
          ' with no fees, which is ' + money.format(r.diySaved - r.net) + ' more than the program leaves you.');
      } else {
        setText('bfVerdict', 'That beats adding ' + money.format(r.M / 12) + ' to each monthly payment yourself (' + money.format(r.diySaved) +
          ') by ' + money.format(r.net - r.diySaved) + ', because each half-payment reaches the lender earlier in the month.');
      }
    } else {
      setText('bfVerdictTitle', 'The fees cost more than the program saves');
      setText('bfVerdict', 'The program saves ' + money.format(Math.max(0, r.saved)) + ' in interest but charges ' + money.format(r.fees) +
        ' in fees. Paying an extra ' + money.format(r.M / 12) + ' a month yourself saves ' + money.format(r.diySaved) + ' for free.');
    }

    var rows = [
      ['Monthly payments (no change)', r.monthly.periods, r.monthly.interest, 0, 0],
      ['Paid biweekly program', r.progMonths, r.prog.interest, r.fees, r.monthly.interest - r.prog.interest - r.fees],
      ['Extra 1/12 each month (do it yourself)', r.diy.periods, r.diy.interest, 0, r.diySaved]
    ];
    var body = el('bfTable');
    body.innerHTML = '';
    rows.forEach(function (row, idx) {
      var tr = document.createElement('tr');
      var cells = [row[0], duration(row[1]), money.format(row[2]), money.format(row[3]), money.format(row[2] + row[3]),
                   idx === 0 ? '–' : (row[4] < 0 ? '−' : '') + money.format(Math.abs(row[4]))];
      cells.forEach(function (text, c) {
        var td = document.createElement(c === 0 ? 'th' : 'td');
        if (c === 0) td.setAttribute('scope', 'row');
        td.textContent = text;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
    setText('bfSooner', 'The program pays the loan off about ' + duration(Math.max(0, monthsSoonerProg)) +
      ' sooner; the do-it-yourself plan about ' + duration(Math.max(0, monthsSoonerDiy)) + ' sooner.');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('bfForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
